const title = $input.first().json.title
//  $input.first()?.json?.data?.transcript?.title || '';

// NORMALIZE
const normalizedTitle = String(title)
  .trim()
  .toLowerCase();

// Matches ONLY:
// new brief
// newbrief
// new-brief
// new_brief
// new    brief
const containsNewBrief = /\bnew[\s_-]*brief\b/i.test(normalizedTitle);

return [
  {
    json: {
      original_title: title,
      normalized_title: normalizedTitle,
      contains_new_brief: containsNewBrief,
      matched_keyword: containsNewBrief ? 'new brief' : null
    }
  }
];

