// =====================================
// n8n CODE NODE
// Check if transcript title contains "brief"
// Production-ready version
// =====================================

// SAFE ACCESS
const title =
  $input.first()?.json?.data?.transcript?.title || '';

// NORMALIZE
const normalizedTitle = String(title)
  .trim()
  .toLowerCase();

// CHECK
const containsBrief =
  normalizedTitle.includes('brief');

// OPTIONAL:
// detect variations like briefing / creative brief
const matchedKeyword =
  containsBrief
    ? 'brief'
    : null;

// OUTPUT
return [
  {
    json: {

      original_title: title,

      normalized_title: normalizedTitle,

      contains_brief: containsBrief,

      matched_keyword: matchedKeyword

    }
  }
];
